function parseDurationToMs(durationStr: string): number {
  const timeRegex = /^(\d+)([shmd])$/i;
  const match = durationStr.trim().match(timeRegex);
  if (!match) return 24 * 60 * 60 * 1000; // 24h default fallback

  const val = parseInt(match[1]);
  const unit = match[2].toLowerCase();
  if (unit === 's') return val * 1000;
  if (unit === 'm') return val * 60 * 1000;
  if (unit === 'h') return val * 60 * 60 * 1000;
  if (unit === 'd') return val * 24 * 60 * 60 * 1000;
  return val * 60 * 1000;
}

async function resolveYoutubeChannelId(inputUrlOrHandle: string): Promise<{ channelId: string; name: string; avatarUrl: string } | null> {
  try {
    let clean = inputUrlOrHandle.trim();
    if (clean.startsWith('UC') && clean.length >= 20) {
      return {
        channelId: clean,
        name: clean,
        avatarUrl: 'https://www.youtube.com/s/desktop/99120668/img/favicon_144x144.png'
      };
    }

    const directChannelMatch = clean.match(/youtube\.com\/channel\/(UC[a-zA-Z0-9_-]{20,})/i);
    if (directChannelMatch) {
      return {
        channelId: directChannelMatch[1],
        name: directChannelMatch[1],
        avatarUrl: 'https://www.youtube.com/s/desktop/99120668/img/favicon_144x144.png'
      };
    }

    let fetchUrl = clean;
    if (!fetchUrl.startsWith('http')) {
      fetchUrl = `https://www.youtube.com/@${fetchUrl.replace(/^@/, '')}`;
    }

    const res = await fetch(fetchUrl, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept-Language': 'fr-FR,fr;q=0.9,en-US;q=0.8,en;q=0.7'
      }
    });

    if (!res.ok) return null;
    const html = await res.text();

    let channelId = '';
    const patterns = [
      /channel_id=(UC[a-zA-Z0-9_-]{20,})/i,
      /channelId":"(UC[a-zA-Z0-9_-]{20,})"/i,
      /externalId":"(UC[a-zA-Z0-9_-]{20,})"/i,
      /browseId":"(UC[a-zA-Z0-9_-]{20,})"/i,
      /<meta itemprop="identifier" content="(UC[a-zA-Z0-9_-]{20,})"/i,
      /<meta itemprop="channelId" content="(UC[a-zA-Z0-9_-]{20,})"/i,
      /https:\/\/www\.youtube\.com\/channel\/(UC[a-zA-Z0-9_-]{20,})/i,
      /https:\/\/www\.youtube\.com\/feeds\/videos\.xml\?channel_id=(UC[a-zA-Z0-9_-]{20,})/i
    ];

    for (const pat of patterns) {
      const match = html.match(pat);
      if (match && match[1]) {
        channelId = match[1];
        break;
      }
    }

    if (!channelId) return null;

    let name = '';
    const titleMatch = html.match(/<meta property="og:title" content="([^"]+)"/i) || html.match(/<title>([^<]+)<\/title>/i);
    if (titleMatch) {
      name = titleMatch[1].replace(' - YouTube', '').trim();
    }

    let avatarUrl = '';
    const imageMatch = html.match(/<meta property="og:image" content="([^"]+)"/i) || html.match(/<link rel="image_src" href="([^"]+)"/i);
    if (imageMatch) {
      avatarUrl = imageMatch[1];
    }

    return {
      channelId,
      name: name || clean,
      avatarUrl: avatarUrl || 'https://www.youtube.com/s/desktop/99120668/img/favicon_144x144.png'
    };
  } catch (err) {
    console.error("Error resolving YouTube channel ID:", err);
    return null;
  }
}

async function fetchYoutubeMetadata(url: string): Promise<{ name: string; avatarUrl: string; channelId?: string }> {
  const resolved = await resolveYoutubeChannelId(url);
  if (resolved) {
    return {
      name: resolved.name,
      avatarUrl: resolved.avatarUrl,
      channelId: resolved.channelId
    };
  }
  let handle = 'Chaîne';
  try {
    const u = new URL(url);
    handle = u.pathname.split('/').filter(Boolean).pop() || 'Chaîne';
  } catch {}
  return {
    name: handle,
    avatarUrl: 'https://www.youtube.com/s/desktop/99120668/img/favicon_144x144.png'
  };
}

async function getLatestYoutubeVideo(channelUrlOrId: string): Promise<{ id: string; title: string; url: string; channelTitle?: string } | null> {
  try {
    let channelId = channelUrlOrId.trim();

    if (!channelId.startsWith('UC') || channelId.length < 20) {
      const resolved = await resolveYoutubeChannelId(channelUrlOrId);
      if (resolved && resolved.channelId) {
        channelId = resolved.channelId;
      } else {
        return null;
      }
    }

    const rssRes = await fetch(`https://www.youtube.com/feeds/videos.xml?channel_id=${channelId}`, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept-Language': 'fr-FR,fr;q=0.9,en-US;q=0.8,en;q=0.7'
      }
    });

    if (!rssRes.ok) return null;
    const xml = await rssRes.text();

    const entryMatch = xml.match(/<entry>([\s\S]*?)<\/entry>/i);
    if (!entryMatch) return null;
    const entry = entryMatch[1];

    const videoIdMatch = entry.match(/<yt:videoId>([^<]+)<\/yt:videoId>/i) ||
                         entry.match(/<id>yt:video:([^<]+)<\/id>/i) ||
                         entry.match(/v=([a-zA-Z0-9_-]{11})/i);

    const titleMatch = entry.match(/<title>([^<]+)<\/title>/i);
    const linkMatch = entry.match(/<link[^>]*href="([^"]+)"/i);

    const feedAuthorMatch = xml.match(/<author>\s*<name>([^<]+)<\/name>/i);
    const channelTitle = feedAuthorMatch ? feedAuthorMatch[1].trim() : undefined;

    if (videoIdMatch && titleMatch) {
      const cleanTitle = titleMatch[1]
        .replace(/&amp;/g, '&')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'")
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>');

      const videoId = videoIdMatch[1].trim();
      return {
        id: videoId,
        title: cleanTitle,
        url: linkMatch ? linkMatch[1] : `https://www.youtube.com/watch?v=${videoId}`,
        channelTitle
      };
    }
  } catch (err) {
    console.error("Error fetching latest youtube video:", err);
  }
  return null;
}

