// --- Music Helpers & Panel Builder ---
const buildLiveMusicPanel = (guildId: string, session: any, guild: any) => {
  const currentSong = session.songs[session.currentSongIndex];
  
  const embed = new EmbedBuilder()
    .setTitle('🎵 PANNEAU DE CONTRÔLE MUSICAL EN DIRECT')
    .setTimestamp();

  if (!currentSong) {
    embed.setColor(0x95A5A6); // Neutral Grey
    embed.setDescription(
      `🎧 **Aucune musique en cours de lecture.**\n\n` +
      `Tapez \`/musique [titre ou lien]\` ou cliquez sur le bouton **➕ Ajouter** ci-dessous pour lancer votre premier morceau !\n\n` +
      `🎛️ **Contrôleur actuel :** ${session.controllerId ? `<@${session.controllerId}>` : '*Aucun (premier arrivé = contrôleur)*'}\n` +
      `🔊 **Volume :** \`${session.volume}%\` | **Statut :** \`⏹️ Inactif\``
    );
  } else {
    embed.setColor(session.isPlaying ? 0x2ECC71 : 0xE67E22); // Green if playing, Orange if paused
    
    const controllerText = session.controllerId
      ? `<@${session.controllerId}>`
      : '*Libre (cliquez sur un bouton pour prendre le contrôle)*';

    const upcomingSongs = session.songs.slice(session.currentSongIndex + 1, session.currentSongIndex + 4);
    let nextText = '*Aucun morceau suivant (utilisez ➕ Ajouter)*';
    if (upcomingSongs.length > 0) {
      nextText = upcomingSongs.map((s: any, idx: number) => `**${idx + 1}.** [${s.title}](${s.url || 'https://youtube.com'}) \`(${s.duration || '03:30'})\` — <@${s.requestedById}>`).join('\n');
    }

    const progressBar = session.isPlaying ? '🔘▬▬▬▬▬▬▬▬▬▬' : '▬🔘▬▬▬▬▬▬▬▬▬';

    embed.setDescription(
      `💿 **En cours :** **[${currentSong.title}](${currentSong.url || 'https://youtube.com'})**\n` +
      `⏱️ **Progression :** \`${progressBar}\` \`(${currentSong.duration || '03:30'})\`\n` +
      `👤 **Demandé par :** <@${currentSong.requestedById}>\n\n` +
      `🎛️ **Contrôleur de session :** ${controllerText}\n` +
      `🔊 **Volume :** \`${session.volume}%\` | **Statut :** ${session.isPlaying ? '▶️ En lecture' : '⏸️ En pause'}\n` +
      `🔁 **Boucle :** \`${session.isLoop ? 'Oui' : 'Non'}\` | 🔀 **Aléatoire :** \`${session.isShuffle ? 'Oui' : 'Non'}\`\n\n` +
      `📋 **À venir dans la file d'attente :**\n${nextText}`
    );

    if (currentSong.thumbnail) {
      embed.setThumbnail(currentSong.thumbnail);
    } else {
      embed.setThumbnail('https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=500&auto=format&fit=crop&q=60');
    }
  }

  embed.setFooter({
    text: `Komorebi Music System • Seul le contrôleur ou le staff peut modifier la lecture`,
    iconURL: guild?.iconURL() || undefined
  });

  const row1 = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder()
      .setCustomId('music_btn_play_pause')
      .setEmoji(session.isPlaying ? '⏸️' : '▶️')
      .setLabel(session.isPlaying ? 'Pause' : 'Reprendre')
      .setStyle(session.isPlaying ? ButtonStyle.Primary : ButtonStyle.Success),
    new ButtonBuilder()
      .setCustomId('music_btn_skip')
      .setEmoji('⏭️')
      .setLabel('Suivant')
      .setStyle(ButtonStyle.Secondary),
    new ButtonBuilder()
      .setCustomId('music_btn_shuffle')
      .setEmoji('🔀')
      .setLabel('Aléatoire')
      .setStyle(session.isShuffle ? ButtonStyle.Success : ButtonStyle.Secondary),
    new ButtonBuilder()
      .setCustomId('music_btn_loop')
      .setEmoji('🔁')
      .setLabel('Boucle')
      .setStyle(session.isLoop ? ButtonStyle.Success : ButtonStyle.Secondary),
    new ButtonBuilder()
      .setCustomId('music_btn_add_modal')
      .setEmoji('➕')
      .setLabel('Ajouter')
      .setStyle(ButtonStyle.Primary)
  );

  const row2 = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder()
      .setCustomId('music_btn_queue')
      .setEmoji('📜')
      .setLabel("File d'attente")
      .setStyle(ButtonStyle.Secondary),
    new ButtonBuilder()
      .setCustomId('music_btn_stop')
      .setEmoji('⏹️')
      .setLabel('Stop / Quitter')
      .setStyle(ButtonStyle.Danger)
  );

  const selectMenu = new StringSelectMenuBuilder()
    .setCustomId('music_select_volume')
    .setPlaceholder(`🔊 Réglage du Volume (${session.volume}%)`)
    .addOptions([
      { label: '🔊 Volume 25%', value: '25', description: 'Volume très bas', default: session.volume === 25 },
      { label: '🔊 Volume 50%', value: '50', description: 'Volume modéré', default: session.volume === 50 },
      { label: '🔊 Volume 75%', value: '75', description: 'Volume standard', default: session.volume === 75 },
      { label: '🔊 Volume 100%', value: '100', description: 'Volume recommandé', default: session.volume === 100 },
      { label: '🔊 Volume 125%', value: '125', description: 'Volume élevé', default: session.volume === 125 },
      { label: '🔊 Volume 150%', value: '150', description: 'Volume maximal boosté', default: session.volume === 150 }
    ]);

  const row3 = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(selectMenu);

  return { embeds: [embed], components: [row1, row2, row3] };
};

