  // Returns the valid Gemini API key from config or environment fallback
  private getGeminiApiKey(config: BotConfig): string {
    const key = config.apiKey || '';
    if (!key || key.startsWith('apf_') || !key.startsWith('AIzaSy')) {
      return process.env.GEMINI_API_KEY || '';
    }
    return key;
  }

