  // Get current stored configuration or create defaults
  async getOrCreateConfig(guildId?: string | null): Promise<BotConfig> {
    const docId = guildId || 'main';
    const ref = this.db.collection('bot_config').doc(docId);
    const doc = await ref.get();
    if (!doc.exists) {
      const defaultConfig = this.getDefaultConfig();
      await ref.set(defaultConfig);
      return defaultConfig;
    }
    const data = doc.data() as BotConfig;
    return { ...this.getDefaultConfig(), ...data };
  }

  async updateConfigInDb(updates: Partial<BotConfig>, guildId?: string | null): Promise<void> {
    const docId = guildId || 'main';
    const ref = this.db.collection('bot_config').doc(docId);
    await ref.set(updates, { merge: true });
  }

  // Intercept and translate payloads dynamically for English-configured servers
  private translatePayload(options: any, lang: 'fr' | 'en'): any {
    if (lang !== 'en') return options;
    if (!options) return options;

    if (typeof options === 'string') {
      return this.translateText(options);
    }

    const copy = { ...options };

    if (copy.content && typeof copy.content === 'string') {
      copy.content = this.translateText(copy.content);
    }

    if (copy.embeds && Array.isArray(copy.embeds)) {
      copy.embeds = copy.embeds.map((embed: any) => {
        let rawEmbed: any;
        if (embed && typeof embed.toJSON === 'function') {
          rawEmbed = embed.toJSON();
        } else {
          rawEmbed = { ...embed };
        }

        if (rawEmbed) {
          if (rawEmbed.title) {
            rawEmbed.title = this.translateText(rawEmbed.title);
          }
          if (rawEmbed.description) {
            rawEmbed.description = this.translateText(rawEmbed.description);
          }
          if (rawEmbed.fields && Array.isArray(rawEmbed.fields)) {
            rawEmbed.fields = rawEmbed.fields.map((field: any) => ({
              ...field,
              name: this.translateText(field.name),
              value: this.translateText(field.value)
            }));
          }
          if (rawEmbed.footer && rawEmbed.footer.text) {
            rawEmbed.footer.text = this.translateText(rawEmbed.footer.text);
          }
        }
        return rawEmbed;
      });
    }

    if (copy.components && Array.isArray(copy.components)) {
      copy.components = copy.components.map((row: any) => {
        let rawRow: any;
        if (row && typeof row.toJSON === 'function') {
          rawRow = row.toJSON();
        } else {
          rawRow = { ...row };
        }

        if (rawRow && rawRow.components && Array.isArray(rawRow.components)) {
          rawRow.components = rawRow.components.map((comp: any) => {
            const rawComp = { ...comp };
            if (rawComp.label) {
              rawComp.label = this.translateText(rawComp.label);
            }
            if (rawComp.placeholder) {
              rawComp.placeholder = this.translateText(rawComp.placeholder);
            }
            if (rawComp.options && Array.isArray(rawComp.options)) {
              rawComp.options = rawComp.options.map((opt: any) => ({
                ...opt,
                label: this.translateText(opt.label),
                description: opt.description ? this.translateText(opt.description) : undefined
              }));
            }
            return rawComp;
          });
        }
        return rawRow;
      });
    }

    return copy;
  }

