    // Slash command and button interaction handler
    this.client.on('interactionCreate', async (interaction: Interaction) => {
      try {
        if (interaction.guild) {
          await interaction.guild.emojis.fetch().catch(() => null);
        }

        // Apply dynamic English translation wrapping
        const guildId = interaction.guildId || 'main';
        const config = await this.getOrCreateConfig(guildId);
        const lang = config.language || 'fr';

        if (lang === 'en') {
          let isInteractionAdmin = false;
          if (interaction.isChatInputCommand() && interaction.commandName === 'admin') {
            isInteractionAdmin = true;
          } else if ((interaction as any).customId) {
            const cid = (interaction as any).customId;
            if (cid.startsWith('admin_')) {
              isInteractionAdmin = true;
            }
          }

          if (!isInteractionAdmin) {
            if (interaction.isRepliable()) {
              if (interaction.reply) {
                const origReply = interaction.reply.bind(interaction);
                interaction.reply = async (options: any) => {
                  return origReply(this.translatePayload(options, 'en'));
                };
              }
              if (interaction.editReply) {
                const origEditReply = interaction.editReply.bind(interaction);
                interaction.editReply = async (options: any) => {
                  return origEditReply(this.translatePayload(options, 'en'));
                };
              }
              if (interaction.followUp) {
                const origFollowUp = interaction.followUp.bind(interaction);
                interaction.followUp = async (options: any) => {
                  return origFollowUp(this.translatePayload(options, 'en'));
                };
              }
              const interAny = interaction as any;
              if (interAny.update) {
                const origUpdate = interAny.update.bind(interAny);
                interAny.update = async (options: any) => {
                  return origUpdate(this.translatePayload(options, 'en'));
                };
              }
            }
          }
        }

        if (interaction.isChatInputCommand()) {
          await this.handleSlashCommand(interaction);
        } else if (interaction.isButton()) {
          await this.handleButtonInteraction(interaction);
        } else if (interaction.isStringSelectMenu() || interaction.isChannelSelectMenu() || interaction.isRoleSelectMenu()) {
          await this.handleSelectMenuInteraction(interaction);
        } else if (interaction.isModalSubmit()) {
          await this.handleModalSubmitInteraction(interaction);
        }
      } catch (err: any) {
        console.error('Interaction error:', err);
        if (interaction.isRepliable()) {
          try {
            await interaction.reply({
              content: `Une erreur est survenue lors de l'exécution de l'action : ${err?.message || err}`,
              ephemeral: true
            });
          } catch {}
        }
      }
    });

    // Message creation handler (for AI chat, tickets, etc.)
    this.client.on('messageCreate', async (message: Message) => {
      try {
        if (message.author.bot || !this.client) return;
        await this.handleMessage(message);
      } catch (err: any) {
        console.error('Message handling error:', err);
      }
    });

    // Guild Member Add event (Welcome Message)
    this.client.on('guildMemberAdd', async (member) => {
      try {
        const config = await this.getOrCreateConfig(member.guild.id);

        // Clear leftAt timestamp if member returned before 14 days
        const userProfile = await this.getOrCreateUserProfile(member.id, member.user.username, member.guild.id);
        if (userProfile.leftAt) {
          userProfile.leftAt = null;
          await this.db.collection('users').doc(userProfile.id).set({ leftAt: null }, { merge: true });
        }

        // Track member join invite
        const inviteInfo = await this.trackMemberJoinInvite(member);

        // Log to log-membres
        const memberJoinEmbed = new EmbedBuilder()
          .setTitle('📥 Arrivée d\'un membre')
          .setDescription(`${member} (${member.user.tag}) a rejoint le serveur.`)
          .setThumbnail(member.user.displayAvatarURL() || null)
          .setColor(0x2ECC71)
          .addFields(
            { name: 'Compte créé le', value: `<t:${Math.floor(member.user.createdTimestamp / 1000)}:R>`, inline: true },
            { name: 'ID Utilisateur', value: `\`${member.id}\``, inline: true },
            { name: '📩 Invité par', value: inviteInfo.inviterId ? `<@${inviteInfo.inviterId}>` : 'Lien inconnu / Indéterminé', inline: true }
          )
          .setTimestamp();
        await this.sendRealtimeLog(member.guild.id, 'membres', memberJoinEmbed);

        // --- Bot Invite Detector ---
        if (member.user.bot) {
          const fetchedLogs = await member.guild.fetchAuditLogs({
            limit: 1,
            type: AuditLogEvent.BotAdd
          }).catch(() => null);
          const botEntry = fetchedLogs?.entries.first();
          const inviter = botEntry && botEntry.target?.id === member.id ? botEntry.executor : null;

          const botAddEmbed = new EmbedBuilder()
            .setTitle('🤖 Nouveau Bot Invité')
            .setDescription(`Un nouveau bot a été invité sur le serveur.`)
            .setThumbnail(member.user.displayAvatarURL() || null)
            .setColor(0x9B59B6)
            .addFields(
              { name: 'Bot', value: `${member} (\`${member.user.tag}\`)`, inline: true },
              { name: 'Invité par', value: inviter ? `${inviter} (\`${inviter.id}\`)` : 'Inconnu', inline: true },
              { name: 'ID du Bot', value: `\`${member.id}\``, inline: false }
            )
            .setTimestamp();
          await this.sendRealtimeLog(member.guild.id, 'serveur', botAddEmbed);
        }

        // --- Auto-Role Module (Bots excluded) ---
        if (!member.user.bot && config.autoroleEnabled && config.autoroleRoleId) {
          try {
            const roleIds = config.autoroleRoleId.split(',').map((id: string) => id.trim()).filter(Boolean);
            for (const rId of roleIds) {
              const role = member.guild.roles.cache.get(rId);
              if (role) {
                await member.roles.add(role).catch((err: any) => console.error(`Failed to assign auto-role ${rId}:`, err));
                console.log(`Auto-Role assigned: added role ${role.name} to member ${member.user.username}`);
              }
            }
          } catch (roleErr) {
            console.error(`Failed to assign auto-role to ${member.user.username}:`, roleErr);
          }
        }

        const channelId = config.welcomeChannelId || config.channelBienvenueId;
        const isEnabled = config.welcomeEnabled !== false && !!channelId;
        if (isEnabled && channelId) {
          const channel = member.guild.channels.cache.get(channelId);
          if (channel?.isTextBased()) {
            const memberCount = member.guild.memberCount;
            const file = new AttachmentBuilder('./src/assets/images/welcome_banner_1783419407101.jpg', { name: 'welcome_banner.jpg' });

            const welcomeEmbed = new EmbedBuilder()
              .setTitle(`✨ BIENVENUE SUR ${member.guild.name.toUpperCase()} ! ✨`)
              .setDescription(
                `### Bienvenue parmi nous, ${member} ! 🎉\n\n` +
                `✨ **Identifiant :** \`${member.user.username}\`\n` +
                `🌟 **Membre N° :** \`${memberCount}\`\n\n` +
                `Nous sommes extrêmement heureux de t'accueillir dans notre communauté !`
              )
              .setColor(0x2ECC71)
              .setThumbnail(member.user.displayAvatarURL() || null)
              .setImage('attachment://welcome_banner.jpg')
              .setFooter({ text: `Komorebi • Nouveau membre v6` })
              .setTimestamp();

            await (channel as any).send({ content: `👋 ${member}, bienvenue sur le serveur !`, embeds: [welcomeEmbed], files: [file] }).catch(() => {});
          }
        }

        // --- Captcha Verification Trigger ---
        if (config.guardCaptcha) {
          await this.setupCaptchaSystem(member.guild, config);
          const freshConfig = await this.getOrCreateConfig(member.guild.id);

          // Assign Unverified Role immediately
          const unverifiedRoleId = freshConfig.guardCaptchaRoleUnverifiedId;
          if (unverifiedRoleId) {
            const unverifiedRole = member.guild.roles.cache.get(unverifiedRoleId);
            if (unverifiedRole) {
              await member.roles.add(unverifiedRole).catch((e: any) => console.error('Failed to assign unverified role on join:', e));
            }
          }

          let chan = freshConfig.guardCaptchaChannelId ? member.guild.channels.cache.get(freshConfig.guardCaptchaChannelId) : null;
          if (!chan) {
            chan = member.guild.channels.cache.find((c: any) => c.name.includes('verification-captcha') || c.name.includes('captcha'));
          }

          if (chan && chan.isTextBased()) {
            const code = this.generateCaptchaCode();
            const imgBuffer = await this.generateCaptchaImage(code);
            const attachment = new AttachmentBuilder(imgBuffer, { name: 'captcha.png' });
            const expiresAt = Date.now() + (freshConfig.guardCaptchaTimeoutMinutes || 10) * 60 * 1000;

            await this.db.collection('pending_captchas').doc(`${member.guild.id}_${member.id}`).set({
              guildId: member.guild.id,
              userId: member.id,
              answer: code.toLowerCase(),
              attemptsLeft: freshConfig.guardCaptchaMaxAttempts || 3,
              expiresAt,
              createdAt: Date.now()
            });

            const captchaEmbed = new EmbedBuilder()
              .setTitle(`🧩 VÉRIFICATION CAPTCHA ANTI-BOT • ${member.user.username}`)
              .setDescription(
                `👋 **Bienvenue ${member} sur ${member.guild.name} !**\n\n` +
                `🔒 Pour des raisons de sécurité et filtrer les bots malveillants, tous les salons vous sont masqués.\n\n` +
                `📝 **Veuillez recopier exactement le code à 5 caractères affiché sur l'image ci-dessous :**\n` +
                `• *Entrez votre code via le bouton ou tapez-le directement dans ce salon.*\n\n` +
                `⏱️ **Délai accordé :** ${freshConfig.guardCaptchaTimeoutMinutes || 10} minutes\n` +
                `⚠️ **Tentatives autorisées :** ${freshConfig.guardCaptchaMaxAttempts || 3}`
              )
              .setColor(0xF1C40F)
              .setImage('attachment://captcha.png')
              .setThumbnail(member.user.displayAvatarURL() || null)
              .setFooter({ text: 'Komorebi • Protection Anti-Bot & Anti-Raid IA' })
              .setTimestamp();

            const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
              new ButtonBuilder()
                .setCustomId(`captcha_solve_${member.id}`)
                .setLabel('🧩 Saisir le Code Captcha')
                .setStyle(ButtonStyle.Success)
            );

            await (chan as any).send({ content: `👋 ${member}`, embeds: [captchaEmbed], files: [attachment], components: [row] }).catch(() => null);
          }
        }
      } catch (err) {
        console.error('Error in guildMemberAdd handler:', err);
      }
    });

    // Guild Member Remove event (Departure Message & 14-day data retention timer)
    this.client.on('guildMemberRemove', async (member) => {
      try {
        // Record leftAt timestamp on user profile
        const userProfile = await this.getOrCreateUserProfile(member.id, member.user.username, member.guild.id);
        userProfile.leftAt = Date.now();
        await this.db.collection('users').doc(userProfile.id).set({ leftAt: Date.now() }, { merge: true });

        // Instantly update live economy leaderboard for this guild upon member departure
        this.updateGuildMoneyLeaderboard(member.guild.id).catch(() => null);

        const config = await this.getOrCreateConfig(member.guild.id);

        // Log to log-membres
        const memberLeaveEmbed = new EmbedBuilder()
          .setTitle('📤 Départ d\'un membre')
          .setDescription(`${member} (${member.user.tag}) a quitté le serveur.`)
          .setThumbnail(member.user.displayAvatarURL() || null)
          .setColor(0xE74C3C)
          .addFields(
            { name: 'Rejoint le', value: member.joinedTimestamp ? `<t:${Math.floor(member.joinedTimestamp / 1000)}:R>` : 'Inconnu', inline: true },
            { name: 'ID Utilisateur', value: `\`${member.id}\``, inline: true }
          )
          .setTimestamp();
        await this.sendRealtimeLog(member.guild.id, 'membres', memberLeaveEmbed);

        // Check if kicked
        const fetchedLogs = await member.guild.fetchAuditLogs({
          limit: 1,
          type: AuditLogEvent.MemberKick
        }).catch(() => null);
        const kickEntry = fetchedLogs?.entries.first();
        const isRecent = kickEntry ? (Date.now() - kickEntry.createdTimestamp < 5000) : false;
        if (kickEntry && kickEntry.target?.id === member.id && isRecent) {
          const executor = kickEntry.executor;
          const reason = kickEntry.reason || 'Aucune raison spécifiée';

          const kickEmbed = new EmbedBuilder()
            .setTitle('👢 Membre Expulsé (Kick)')
            .setDescription(`**${member.user.tag}** a été expulsé (kick) du serveur.`)
            .setThumbnail(member.user.displayAvatarURL() || null)
            .setColor(0xE67E22)
            .addFields(
              { name: 'Cible', value: `${member} (\`${member.id}\`)`, inline: true },
              { name: 'Expulsé par', value: executor ? `${executor} (\`${executor.id}\`)` : 'Inconnu', inline: true },
              { name: 'Raison', value: `\`${reason}\``, inline: false }
            )
            .setTimestamp();
          await this.sendRealtimeLog(member.guild.id, 'moderation', kickEmbed);
        }

        const channelId = config.leaveChannelId || config.channelAuRevoirId;
        const isEnabled = config.leaveEnabled !== false && !!channelId;
        if (isEnabled && channelId) {
          const channel = member.guild.channels.cache.get(channelId);
          if (channel?.isTextBased()) {
            const memberCount = member.guild.memberCount;
            const file = new AttachmentBuilder('./src/assets/images/leave_banner_1783419420801.jpg', { name: 'leave_banner.jpg' });

            const leaveEmbed = new EmbedBuilder()
              .setTitle(`😢 UN MEMBRE NOUS QUITTE... 😢`)
              .setDescription(
                `### Au revoir, **${member.user.username}**...\n\n` +
                `📉 **Membres restants :** \`${memberCount}\`\n\n` +
                `Nous espérons te revoir très bientôt parmi nous !`
              )
              .setColor(0xE74C3C)
              .setThumbnail(member.user.displayAvatarURL() || null)
              .setImage('attachment://leave_banner.jpg')
              .setFooter({ text: `Komorebi • Membre sur le départ` })
              .setTimestamp();

            await (channel as any).send({ embeds: [leaveEmbed], files: [file] }).catch(() => {});
          }
        }
      } catch (err) {
        console.error('Error in guildMemberRemove handler:', err);
      }
    });

    // --- Real-time Logs Event Listeners ---
    this.client.on('messageDelete', async (message: any) => {
      try {
        if (!message.guild || message.author?.bot) return;

        // --- DEDUPLICATION CACHE ---
        const messageId = message.id;
        if (this.loggedDeletions.has(messageId)) {
          return; // Already logged this deletion
        }
        this.loggedDeletions.add(messageId);
        setTimeout(() => this.loggedDeletions.delete(messageId), 10000); // clear from cache after 10 seconds

        let deletedByText = `<@${message.author.id}> (L'auteur lui-même)`;
        let actionText = `Message supprimé par l'auteur lui-même.`;

        // Wait brief moment for Discord API audit log sync
        await new Promise(resolve => setTimeout(resolve, 1000));

        const fetchedLogs = await message.guild.fetchAuditLogs({
          limit: 10,
          type: AuditLogEvent.MessageDelete,
        }).catch(() => null);

        if (fetchedLogs && fetchedLogs.entries && fetchedLogs.entries.size > 0) {
          const now = Date.now();
          const entries = Array.from(fetchedLogs.entries.values());

          const entry = entries.find((e: any) => {
            const entryTime = e.createdTimestamp || (e.createdAt ? e.createdAt.getTime() : 0);
            const timeDiff = Math.abs(now - entryTime);
            if (timeDiff > 30000) return false;

            if (!e.executor || e.executor.id === message.author.id) return false;

            const targetId = e.target?.id || e.target;
            const targetMatches = !targetId || targetId === message.author.id;

            let extraChanId: string | null = null;
            if (e.extra) {
              if (typeof e.extra.channel === 'string') extraChanId = e.extra.channel;
              else if (e.extra.channel && typeof e.extra.channel.id === 'string') extraChanId = e.extra.channel.id;
            }
            const channelMatches = !extraChanId || extraChanId === message.channelId || extraChanId === message.channel?.id;

            return targetMatches && channelMatches;
          });

          const auditEntry = entry as any;
          if (auditEntry && auditEntry.executor && auditEntry.executor.id !== message.author.id) {
            const tagStr = auditEntry.executor.tag || auditEntry.executor.username || auditEntry.executor.id;
            deletedByText = `<@${auditEntry.executor.id}> (Tag: \`${tagStr}\` | ID: \`${auditEntry.executor.id}\`)`;
            actionText = `🚨 **<@${auditEntry.executor.id}>** (Staff/Modérateur) a supprimé le message de **<@${message.author.id}>**`;
          }
        }

        const embed = new EmbedBuilder()
          .setTitle('🗑️ ALERTE LOGS - MESSAGE SUPPRIMÉ 🗑️')
          .setDescription(`Un message a été supprimé sur le serveur de façon définitive.`)
          .setColor(0xE74C3C)
          .addFields(
            { name: '👤 Auteur du message', value: `<@${message.author.id}> (Tag: \`${message.author.tag}\` | ID: \`${message.author.id}\`)`, inline: false },
            { name: '📺 Salon', value: `<#${message.channelId}>`, inline: false },
            { name: '⏰ Horodatage', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`, inline: false },
            { name: '💬 Contenu du message', value: `\`\`\`\n${message.content?.slice(0, 1000) || '*(Aucun contenu textuel)*'}\n\`\`\``, inline: false },
            { name: '⚙️ Action de Modération', value: `• ${actionText}\n• Supprimé par : ${deletedByText}`, inline: false }
          )
          .setFooter({ text: `Komorebi Logs • Système de Surveillance des Messages` })
          .setTimestamp();

        await this.sendRealtimeLog(message.guild.id, 'messages', embed);
      } catch (err) {
        console.error('Error in messageDelete log:', err);
      }
    });

    this.client.on('messageUpdate', async (oldMessage: any, newMessage: any) => {
      try {
        if (!newMessage.guild || newMessage.author?.bot) return;
        if (oldMessage.content === newMessage.content) return;

        // --- DEDUPLICATION CACHE ---
        const updateKey = `${newMessage.id}_${newMessage.content}`;
        const existingUpdate = this.loggedUpdates.get(newMessage.id);
        if (existingUpdate && existingUpdate.content === newMessage.content && (Date.now() - existingUpdate.time < 5000)) {
          return; // Already logged this edit
        }
        this.loggedUpdates.set(newMessage.id, { content: newMessage.content, time: Date.now() });
        setTimeout(() => this.loggedUpdates.delete(newMessage.id), 15000); // clear from memory

        const embed = new EmbedBuilder()
          .setTitle('📝 ALERTE LOGS - MESSAGE MODIFIÉ 📝')
          .setDescription(`Un message a été édité par son auteur sur le serveur.`)
          .setColor(0xE67E22)
          .addFields(
            { name: '👤 Auteur du message', value: `<@${newMessage.author.id}> (Tag: \`${newMessage.author.tag}\` | ID: \`${newMessage.author.id}\`)`, inline: false },
            { name: '📺 Salon', value: `<#${newMessage.channelId}>`, inline: false },
            { name: '⏰ Horodatage', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`, inline: false },
            { name: '❌ Avant Modification', value: `\`\`\`\n${oldMessage.content?.slice(0, 1000) || '*(Aucun contenu)*'}\n\`\`\``, inline: false },
            { name: '✅ Après Modification', value: `\`\`\`\n${newMessage.content?.slice(0, 1000) || '*(Aucun contenu)*'}\n\`\`\``, inline: false },
            { name: '🔗 Lien du Message', value: `[Cliquez pour voir le message](${newMessage.url})`, inline: false }
          )
          .setFooter({ text: `Komorebi Logs • Système de Surveillance des Messages` })
          .setTimestamp();

        await this.sendRealtimeLog(newMessage.guild.id, 'messages', embed);
      } catch (err) {
        console.error('Error in messageUpdate log:', err);
      }
    });

    this.client.on('guildMemberUpdate', async (oldMember: any, newMember: any) => {
      try {
        if (oldMember.nickname !== newMember.nickname) {
          const embed = new EmbedBuilder()
            .setTitle('👤 Changement de Surnom')
            .setColor(0x3498DB)
            .addFields(
              { name: 'Membre', value: `${newMember} (${newMember.user.tag})` },
              { name: 'Ancien Surnom', value: oldMember.nickname || '*(Aucun)*', inline: true },
              { name: 'Nouveau Surnom', value: newMember.nickname || '*(Aucun)*', inline: true }
            )
            .setTimestamp();
          await this.sendRealtimeLog(newMember.guild.id, 'membres', embed);
        }

        // Detect role changes
        const oldRoles = Array.from(oldMember.roles.cache.keys());
        const newRoles = Array.from(newMember.roles.cache.keys());

        if (JSON.stringify(oldRoles.sort()) !== JSON.stringify(newRoles.sort())) {
          const addedRoles = newMember.roles.cache.filter((r: any) => !oldMember.roles.cache.has(r.id));
          const removedRoles = oldMember.roles.cache.filter((r: any) => !newMember.roles.cache.has(r.id));

          if (addedRoles.size > 0 || removedRoles.size > 0) {
            // Fetch who performed the role update
            const fetchedLogs = await newMember.guild.fetchAuditLogs({
              limit: 1,
              type: AuditLogEvent.MemberRoleUpdate
            }).catch(() => null);
            const entry = fetchedLogs?.entries.first();
            const executor = entry && entry.target?.id === newMember.id ? entry.executor : null;

            const embed = new EmbedBuilder()
              .setTitle('⚙️ Modification des Rôles')
              .setDescription(`Les rôles de **${newMember.user.tag}** ont été mis à jour.`)
              .setThumbnail(newMember.user.displayAvatarURL() || null)
              .setColor(0x9B59B6)
              .addFields(
                { name: 'Membre concerné', value: `${newMember} (\`${newMember.id}\`)`, inline: true },
                { name: 'Modifié par', value: executor ? `${executor} (\`${executor.id}\`)` : 'Inconnu (ou par lui-même/bot)', inline: true }
              )
              .setTimestamp();

            if (addedRoles.size > 0) {
              embed.addFields({
                name: '🟢 Rôles Ajoutés',
                value: Array.from(addedRoles.values()).map((r: any) => `${r} (\`${r.name}\`)`).join('\n')
              });
            }

            if (removedRoles.size > 0) {
              embed.addFields({
                name: '🔴 Rôles Retirés',
                value: Array.from(removedRoles.values()).map((r: any) => `${r} (\`${r.name}\`)`).join('\n')
              });
            }

            await this.sendRealtimeLog(newMember.guild.id, 'serveur', embed);
          }
        }

        // Detect new Server Boost
        if (!oldMember.premiumSince && newMember.premiumSince) {
          const config = await this.getOrCreateConfig(newMember.guild.id);
          if (config.boostEnabled && config.boostChannelId) {
            const celebrateChannel = newMember.guild.channels.cache.get(config.boostChannelId);
            if (celebrateChannel) {
              const boostEmbed = new EmbedBuilder()
                .setTitle('⚡ UN NOUVEAU BOOST SERVEUR ! ⚡')
                .setDescription(`✨ Un immense MERCI à ${newMember} qui vient d'apporter sa puissance magique au serveur en le boostant ! \n\n*Grâce à toi, le serveur gagne de nouveaux pouvoirs et s'illumine !* ❤️`)
                .setColor(0xF47FFF)
                .setThumbnail(newMember.user.displayAvatarURL({ dynamic: true }))
                .setFooter({ text: `Nombre total de boosts : ${newMember.guild.premiumSubscriptionCount || 1}` })
                .setTimestamp();
              
              await (celebrateChannel as any).send({ content: `🎉 **BOOST !** Célébrons ${newMember} !`, embeds: [boostEmbed] }).catch(() => null);
            }
          }
        }
      } catch (err) {
        console.error('Error in guildMemberUpdate log:', err);
      }
    });

    this.client.on('voiceStateUpdate', async (oldState: any, newState: any) => {
      try {
        const guildId = newState.guild.id;
        const member = newState.member;
        if (!member || member.user.bot) return;

        // --- TEMPORARY VOICE CHANNELS (Join-to-Create & Delete empty) ---
        const config = await this.getOrCreateConfig(guildId);
        
        // A) User joins the Creator voice channel -> Create custom voice channel
        if (newState.channelId && config.tempVoiceCreatorChannelId && newState.channelId === config.tempVoiceCreatorChannelId) {
          try {
            const guild = newState.guild;
            const parentId = config.tempVoiceCategoryId || newState.channel?.parentId || null;
            
            const creatorChannel = newState.channel || guild.channels.cache.get(config.tempVoiceCreatorChannelId);
            
            let chanName = `🔊 Salon de ${member.displayName || member.user.username}`;
            if (creatorChannel && chanName.toLowerCase().trim() === creatorChannel.name.toLowerCase().trim()) {
              chanName = `🔊 Privé - ${member.displayName || member.user.username}`;
            }

            // Copy permission overwrites from the creator channel
            const parentOverwrites: any[] = [];
            if (creatorChannel && creatorChannel.permissionOverwrites) {
              creatorChannel.permissionOverwrites.cache.forEach((o: any) => {
                parentOverwrites.push({
                  id: o.id,
                  type: o.type,
                  allow: o.allow.toArray(),
                  deny: o.deny.toArray()
                });
              });
            }

            // Ensure the creator has permissions to manage the channel
            const existingMemberOverwriteIndex = parentOverwrites.findIndex((o: any) => o.id === member.id);
            if (existingMemberOverwriteIndex !== -1) {
              parentOverwrites[existingMemberOverwriteIndex].allow = Array.from(new Set([
                ...parentOverwrites[existingMemberOverwriteIndex].allow,
                'MuteMembers',
                'DeafenMembers',
                'MoveMembers',
                'ManageChannels',
                'Connect',
                'Speak'
              ]));
            } else {
              parentOverwrites.push({
                id: member.id,
                type: 1, // User type (1 for member)
                allow: [
                  PermissionFlagsBits.MuteMembers,
                  PermissionFlagsBits.DeafenMembers,
                  PermissionFlagsBits.MoveMembers,
                  PermissionFlagsBits.ManageChannels,
                  PermissionFlagsBits.Connect,
                  PermissionFlagsBits.Speak
                ],
                deny: []
              });
            }
            
            const newVoiceChan = await guild.channels.create({
              name: chanName,
              type: ChannelType.GuildVoice,
              parent: parentId,
              permissionOverwrites: parentOverwrites
            });
            
            // Move member to the newly created channel
            await member.voice.setChannel(newVoiceChan).catch(() => null);
            
            // Store details in DB
            await this.db.collection('temp_voice_channels').doc(newVoiceChan.id).set({
              channelId: newVoiceChan.id,
              guildId: guildId,
              userId: member.id,
              createdAt: new Date().toISOString()
            });
          } catch (err) {
            console.error('[TEMP-VOICE] Error creating temporary voice channel:', err);
          }
        }

        // B) User leaves any voice channel -> Check if it was temporary and is now empty -> Delete it
        if (oldState.channelId && oldState.channelId !== newState.channelId) {
          try {
            const tempDoc = await this.db.collection('temp_voice_channels').doc(oldState.channelId).get();
            if (tempDoc.exists) {
              const channel = oldState.channel || oldState.guild.channels.cache.get(oldState.channelId);
              if (channel) {
                // Check remaining non-bot members
                const voiceMembers = Array.from(channel.members.values()).filter((m: any) => !m.user.bot);
                if (voiceMembers.length === 0) {
                  await channel.delete('Temporary channel empty').catch(() => null);
                  await this.db.collection('temp_voice_channels').doc(oldState.channelId).delete().catch(() => null);
                }
              } else {
                await this.db.collection('temp_voice_channels').doc(oldState.channelId).delete().catch(() => null);
              }
            }
          } catch (err) {
            console.error('[TEMP-VOICE] Error checking/deleting temporary voice channel:', err);
          }

          // C) Music Session Check: Handle empty voice channel or controller departure
          try {
            const session = this.musicSessions.get(guildId);
            if (session && session.voiceChannelId === oldState.channelId) {
              const channel = oldState.channel || oldState.guild.channels.cache.get(oldState.channelId);
              if (channel) {
                const humanMembers = Array.from(channel.members.values()).filter((m: any) => !m.user.bot);
                if (humanMembers.length === 0) {
                  // All humans left -> Bot leaves voice channel and resets controller
                  try {
                    getVoiceConnection(guildId)?.destroy();
                  } catch (e) {}
                  session.voiceChannelId = null;
                  session.controllerId = null;
                  session.isPlaying = false;
                  await this.refreshMusicPanel(guildId);
                } else if (oldState.member?.id === session.controllerId) {
                  // Controller left -> Silent transfer to next present member
                  session.controllerId = (humanMembers[0] as any).id;
                  await this.refreshMusicPanel(guildId);
                }
              }
            }
          } catch (mErr) {
            console.error('[MUSIC VOICE UPDATE ERROR]:', mErr);
          }
        }

        const embed = new EmbedBuilder().setTimestamp();

        if (!oldState.channelId && newState.channelId) {
          embed
            .setTitle('🎙️ Connexion Vocale')
            .setColor(0x2ECC71)
            .setDescription(`${member} a rejoint le salon vocal <#${newState.channelId}>`);
          await this.sendRealtimeLog(guildId, 'vocal', embed);
        } else if (oldState.channelId && !newState.channelId) {
          embed
            .setTitle('🎙️ Déconnexion Vocale')
            .setColor(0xE74C3C)
            .setDescription(`${member} a quitté le salon vocal <#${oldState.channelId}>`);
          await this.sendRealtimeLog(guildId, 'vocal', embed);
        } else if (oldState.channelId && newState.channelId && oldState.channelId !== newState.channelId) {
          embed
            .setTitle('🎙️ Changement de Salon Vocal')
            .setColor(0x3498DB)
            .setDescription(`${member} s'est déplacé de <#${oldState.channelId}> vers <#${newState.channelId}>`);
          await this.sendRealtimeLog(guildId, 'vocal', embed);
        }
      } catch (err) {
        console.error('Error in voiceStateUpdate log:', err);
      }
    });

