      let next: 'delete' | 'warn' | 'timeout' = 'warn';
      if (current === 'delete') next = 'warn';
      else if (current === 'warn') next = 'timeout';
      else if (current === 'timeout') next = 'delete';
      await this.updateConfigInDb({ badWordsSanction: next }, guild.id);
      const payload = await this.buildConfigGuardPanel(guild, guild.id);
      return interaction.update(payload);
