  // Helper to initialize and setup the Captcha system (roles + dedicated verification channel + channel permissions)
  private async setupCaptchaSystem(guild: any, config: BotConfig): Promise<string> {
    try {
      if (!guild) return '';

      // 1. Ensure Unverified Role exists
      let unverifiedRole = config.guardCaptchaRoleUnverifiedId ? guild.roles.cache.get(config.guardCaptchaRoleUnverifiedId) : null;
      if (!unverifiedRole) {
        unverifiedRole = guild.roles.cache.find((r: any) => r.name === 'Non-Vérifié' || r.name === 'Non-vérifié' || r.name === 'Unverified');
        if (!unverifiedRole) {
          unverifiedRole = await guild.roles.create({
            name: 'Non-Vérifié',
            color: 0x7F8C8D,
            reason: 'Création automatique du rôle Non-Vérifié pour le système Captcha Komorebi'
          }).catch(() => null);
        }
        if (unverifiedRole) {
          await this.updateConfigInDb({ guardCaptchaRoleUnverifiedId: unverifiedRole.id }, guild.id);
        }
      }

      // 2. Ensure Verified Role exists or use reglement_role_id / guardCaptchaRoleVerifiedId
      let verifiedRoleId = config.reglement_role_id || config.guardCaptchaRoleVerifiedId;
      let verifiedRole = verifiedRoleId ? guild.roles.cache.get(verifiedRoleId) : null;
      if (!verifiedRole) {
        verifiedRole = guild.roles.cache.find((r: any) => r.name === 'Vérifié' || r.name === 'Membre');
        if (!verifiedRole) {
          verifiedRole = await guild.roles.create({
            name: 'Vérifié',
            color: 0x2ECC71,
            reason: 'Création automatique du rôle membre vérifié pour le système Captcha Komorebi'
          }).catch(() => null);
        }
        if (verifiedRole) {
          verifiedRoleId = verifiedRole.id;
          await this.updateConfigInDb({ reglement_role_id: verifiedRole.id, guardCaptchaRoleVerifiedId: verifiedRole.id }, guild.id);
        }
      }

      // 3. Ensure dedicated verification channel exists with strict isolated permissions
      let captchaChan = guild.channels.cache.find((c: any) => c.name === 'verification-captcha' || c.name === '🔒-verification-captcha' || c.name === 'captcha');

      const captchaOverwrites: any[] = [
        {
          id: guild.roles.everyone.id,
          deny: [PermissionFlagsBits.ViewChannel]
        },
        {
          id: this.client?.user?.id || guild.members.me?.id,
          allow: [
            PermissionFlagsBits.ViewChannel,
            PermissionFlagsBits.SendMessages,
            PermissionFlagsBits.ManageChannels,
            PermissionFlagsBits.EmbedLinks,
            PermissionFlagsBits.AttachFiles,
            PermissionFlagsBits.ReadMessageHistory
          ]
        }
      ];

      if (unverifiedRole) {
        captchaOverwrites.push({
          id: unverifiedRole.id,
          allow: [
            PermissionFlagsBits.ViewChannel,
            PermissionFlagsBits.SendMessages,
            PermissionFlagsBits.EmbedLinks,
            PermissionFlagsBits.AttachFiles,
            PermissionFlagsBits.ReadMessageHistory
          ]
        });
      }

      if (verifiedRole) {
        captchaOverwrites.push({
          id: verifiedRole.id,
          deny: [PermissionFlagsBits.ViewChannel] // Verified members DO NOT see the verification channel!
        });
      }

      if (!captchaChan) {
        captchaChan = await guild.channels.create({
          name: '🔒-verification-captcha',
          type: ChannelType.GuildText,
          permissionOverwrites: captchaOverwrites,
          reason: 'Création automatique du salon de vérification Captcha isolé Komorebi'
        }).catch(() => null);
      } else {
        // Update permissions on existing captcha channel
        if (unverifiedRole) {
          await captchaChan.permissionOverwrites.edit(unverifiedRole.id, {
            ViewChannel: true,
            SendMessages: true,
            EmbedLinks: true,
            AttachFiles: true,
            ReadMessageHistory: true
          }).catch(() => null);
        }
        if (verifiedRole) {
          await captchaChan.permissionOverwrites.edit(verifiedRole.id, {
            ViewChannel: false
          }).catch(() => null);
        }
        await captchaChan.permissionOverwrites.edit(guild.roles.everyone.id, {
          ViewChannel: false
        }).catch(() => null);
      }

      // 4. Hide all other channels & categories in the server from the Non-Vérifié role
      if (unverifiedRole && guild.channels?.cache) {
        for (const [, ch] of guild.channels.cache) {
          if (captchaChan && ch.id === captchaChan.id) continue;
          await (ch as any).permissionOverwrites?.edit(unverifiedRole.id, {
            ViewChannel: false
          }).catch(() => null);
        }
      }

      if (captchaChan) {
        await this.updateConfigInDb({ guardCaptchaChannelId: captchaChan.id }, guild.id);

        const messages = await captchaChan.messages.fetch({ limit: 10 }).catch(() => null);
        const existingMsg = messages?.find((m: any) => m.author.id === this.client?.user?.id && m.embeds?.[0]?.title?.includes('VÉRIFICATION CAPTCHA'));

        if (!existingMsg) {
          const captchaEmbed = new EmbedBuilder()
            .setTitle('🧩 VÉRIFICATION CAPTCHA OBLIGATOIRE • KOMOREBI')
            .setDescription(
              `Bienvenue sur **${guild.name}** !\n\n` +
              `Pour accéder à l'intégralité du serveur et débloquer tous les salons, vous devez valider votre test de sécurité humain.\n\n` +
              `👉 Un message personnel avec votre image de vérification est généré dès votre arrivée dans ce salon. Vous pouvez aussi cliquer sur le bouton ci-dessous ou écrire votre code directement dans ce salon.`
            )
            .setColor(0xF1C40F)
            .setThumbnail(guild.iconURL({ dynamic: true }) || this.client?.user?.displayAvatarURL() || null)
            .setFooter({ text: '🛡️ Sécurité Anti-Bot & Contrôle Komorebi' })
            .setTimestamp();

          const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
            new ButtonBuilder()
              .setCustomId('captcha_verify_global')
              .setLabel('🧩 Valider le Captcha (Débloquer le serveur)')
              .setStyle(ButtonStyle.Success)
          );

          await captchaChan.send({ embeds: [captchaEmbed], components: [row] }).catch(() => null);
        }
      }

      return captchaChan ? captchaChan.id : '';
    } catch (err: any) {
      console.error('Error in setupCaptchaSystem:', err);
      return '';
    }
  }

