  private async handleTicketAi(message: Message, ticketDoc: any) {
    try {
      const guildId = message.guildId || 'main';
      const config = await this.getOrCreateConfig(guildId);
      if (!config.ticketAiEnabled) return;

      const ticketData = ticketDoc.data();
      if (ticketData?.status === 'closed') return;

      if (message.author.bot) return;

      // Trigger typing indicator to show thinking status
      await (message.channel as any).sendTyping().catch(() => null);

      // Fetch conversation history in this ticket (up to 15 messages)
      const channelMessages = await (message.channel as any).messages.fetch({ limit: 15 }).catch(() => null);
      let conversationText = '';
      if (channelMessages) {
        const sortedMsgs = Array.from(channelMessages.values()).reverse();
        for (const m of sortedMsgs) {
          const msg = m as any;
          const authorName = msg.author.id === this.client?.user?.id ? 'Komorebi (IA)' : msg.author.username;
          conversationText += `[${authorName}]: ${msg.content}\n`;
        }
      }

      const member = message.member;
      const isAdmin = member?.permissions.has(PermissionFlagsBits.Administrator) || message.author.id === message.guild?.ownerId;
      const securityStatus = isAdmin ? "ADMINISTRATEUR (Tu es autorisée à exécuter ses commandes d'action via [EXECUTE_ACTION])" : "MEMBRE SIMPLE (Tu n'as pas le droit d'exécuter ses commandes administratives, refuse poliment)";

      const contextInstructions = 
        `- Tu es dans un ticket d'assistance de support officiel ouvert par l'utilisateur <@${ticketData.userId}> (username: ${ticketData.username}).\n` +
        `- Interlocuteur actuel qui parle : <@${message.author.id}> (username: ${message.author.username}).\n` +
        `- Statut de sécurité de l'interlocuteur qui parle : ${securityStatus}.\n` +
        `- RÈGLE CRITIQUE : Concentre-toi à 100% sur l'utilisateur qui a ouvert le ticket (<@${ticketData.userId}>) pour l'aider au mieux de manière extrêmement concise, naturelle, juste et polie.\n` +
        `- RÈGLE ABSOLUE : Fais des réponses extrêmement courtes (maximum 1 à 2 phrases courtes, pas de longs pavés). Sois chaleureuse, professionnelle et va droit au but. Réponds en français.`;

      const systemPrompt = await this.getSystemPromptForAi(guildId, contextInstructions);

      const finalPrompt = 
        `Voici le fil de la discussion récente dans ce ticket d'assistance :\n` +
        `${conversationText}\n\n` +
        `Rédige maintenant ta réponse polie, naturelle et chaleureuse en tant que support humain sous le nom de Komorebi :`;

      let aiReply = await this.callOpenRouter(finalPrompt, systemPrompt);
      if (aiReply) {
        if (aiReply.startsWith(`Komorebi (IA):`)) {
          aiReply = aiReply.substring(`Komorebi (IA):`.length).trim();
        }
        if (aiReply.startsWith(`${this.client?.user?.username}:`)) {
          aiReply = aiReply.substring(`${this.client?.user?.username}:`.length).trim();
        }

        // Apply reactions, learning, and cleanup
        const cleanedReply = await this.learnFromAiResponse(guildId, message, aiReply);
        if (cleanedReply) {
          await message.reply({ content: cleanedReply });
        }
      }
    } catch (err: any) {
      console.error('Error in handleTicketAi:', err);
      await message.reply({ content: `❌ **Erreur de support IA :** Désolée, je n'ai pas pu générer de réponse automatique pour ce message. Détails : ${err?.message || err}` }).catch(() => null);
    }
  }

  private async sendServersList(interaction: any, page: number, isUpdate = false) {
    try {
      if (!this.client) return;
      const guilds = Array.from(this.client.guilds.cache.values());
      
      if (guilds.length === 0) {
        const errPayload = { content: '❌ Le bot n\'est actuellement présent sur aucun serveur.', ephemeral: true };
        return isUpdate ? interaction.update(errPayload) : interaction.reply(errPayload);
      }

      const pageSize = 5;
      const totalPages = Math.ceil(guilds.length / pageSize);
      
      let targetPage = page;
      if (targetPage < 0) targetPage = 0;
      if (targetPage >= totalPages) targetPage = totalPages - 1;

      const pageGuilds = guilds.slice(targetPage * pageSize, (targetPage + 1) * pageSize);

      let description = `Voici la liste complète des **${guilds.length}** serveurs qui hébergent actuellement Komorebi Bot :\n\n`;
      
      for (const g of pageGuilds) {
        let inviteLink = 'Aucun lien (droits d\'invitation manquants)';
        try {
          const channel = g.channels.cache.find((c: any) => c.type === ChannelType.GuildText && c.permissionsFor(g.members.me).has(PermissionFlagsBits.CreateInstantInvite));
          if (channel) {
            const invite = await (channel as any).createInvite({ maxAge: 0, maxUses: 0 }).catch(() => null);
            if (invite) inviteLink = `[Cliquez ici](${invite.url})`;
          }
        } catch {}
        
        description += `• **${g.name}** (\`${g.id}\` - 👥 **${g.memberCount}** membres)\n  ↳ Invitation : ${inviteLink}\n\n`;
      }

      const embed = new EmbedBuilder()
        .setTitle('🌐 Liste des Serveurs Partenaires')
        .setDescription(description)
        .setColor(0x3498DB)
        .setFooter({ text: `Page ${targetPage + 1} / ${totalPages} • Komorebi Bot` })
        .setTimestamp();

      const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
        new ButtonBuilder()
          .setCustomId(`admin_servers_prev_${targetPage - 1}`)
          .setLabel('⬅️ Précédent')
          .setStyle(ButtonStyle.Primary)
          .setDisabled(targetPage === 0),
        new ButtonBuilder()
          .setCustomId('admin_servers_page_info')
          .setLabel(`Page ${targetPage + 1}/${totalPages}`)
          .setStyle(ButtonStyle.Secondary)
          .setDisabled(true),
        new ButtonBuilder()
          .setCustomId(`admin_servers_next_${targetPage + 1}`)
          .setLabel('➡️ Suivant')
          .setStyle(ButtonStyle.Primary)
          .setDisabled(targetPage === totalPages - 1)
      );

      const payload = { embeds: [embed], components: [row], ephemeral: true };
      return isUpdate ? interaction.update(payload) : interaction.reply(payload);
    } catch (error: any) {
      console.error('Error in sendServersList:', error);
      const errPayload = { content: `❌ Une erreur est survenue lors de la récupération de la liste : ${error.message}`, ephemeral: true };
      return isUpdate ? interaction.update(errPayload) : interaction.reply(errPayload);
    }
  }

